import UIKit

/// Pictures cut from a screen recording of the real mini app (coin logos, the round action
/// buttons, the two banners, the tab bar glyphs), embedded as base64 PNG so the mod needs no
/// resource bundle. Decoded once at 3x and cached.
enum PampGramFakeCryptoBotAssets {
    private static var cache: [String: UIImage] = [:]

    static func image(_ name: String) -> UIImage? {
        if let cached = self.cache[name] {
            return cached
        }
        guard let encoded = self.table[name], let data = Data(base64Encoded: encoded), let image = UIImage(data: data, scale: 3.0) else {
            return nil
        }
        self.cache[name] = image
        return image
    }

    private static let table: [String: String] = [
        "coin_USDT": "",
        "coin_GRAM": "",
        "coin_SOL": "",
        "coin_TRX": "",
        "coin_BTC": "",
        "coin_ETH": "",
        "coin_DOGE": "",
        "coin_LTC": "",
        "coin_BNB": "",
        "coin_USDC": "",
        "coin_XAUT": "",
        "act_deposit": "",
        "act_withdraw": "",
        "act_history": "",
        "top_scan": "",
        "top_image": "",
        "top_currency": "",
        "banner_autumn": "",
        "banner_p2p": "",
        "net_TON": "",
        "banner_qr": "",
        "banner_exchange": "",
        "tab_wallet": "",
        "tab_exchange": "",
        "tab_swap": "",
        "tab_p2p": "",
        "tab_more": "",
    ]
}
